from pathlib import Path
TODAY='2026-06-18'

def header(title):
    return f"# {title}\n\n> - 引用级别：✅可供学习参考\n> - 最后更新：{TODAY}\n\n"

def write(path,text):
    Path(path).write_text(text.strip()+"\n", encoding='utf-8')

def article(title, path, positioning, concepts, asks, triage, categories, scenarios, analysis):
    c='\n\n'.join(f"### {i+1}. {h}\n\n{b}" for i,(h,b) in enumerate(concepts))
    a='\n'.join(f"- {x}" for x in asks)
    t='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} | {x[3]} |" for x in triage)
    cats='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} |" for x in categories)
    sc='\n'.join(f"| {x[0]} | {x[1]} | {x[2]} |" for x in scenarios)
    an='\n'.join(f"- **{k}：** {v}" for k,v in analysis)
    write(path, header(title)+f'''## 一句话定位\n\n{positioning}\n\n## 一、准确解释：三个概念分别是什么\n\n{c}\n\n## 二、药店咨询首先要问什么\n\n{a}\n\n## 三、轻症、需药师判断、应就医的分层\n\n| 分层 | 典型表现 | 药店/平台可以做什么 | 不应做什么 |\n|---|---|---|---|\n{t}\n\n## 四、常见品类与药店咨询口径\n\n| 品类/服务 | 适合讨论的场景 | 药师提醒点 |\n|---|---|---|\n{cats}\n\n## 五、即时零售医药场景拆解\n\n| 场景 | 用户需求 | 平台/药店承接点 |\n|---|---|---|\n{sc}\n\n## 六、对平台、药店、药企的业务分析\n\n{an}\n''')

